USE `gmodelo_dbp`;
SET NAMES utf8mb4;

INSERT INTO ia_prompts (codigo,nome_pt,nome_en,nome_es,prompt_pt,prompt_en,prompt_es)
SELECT x.codigo,x.nome_pt,x.nome_en,x.nome_es,x.prompt_pt,x.prompt_en,x.prompt_es
FROM (
    SELECT 'ML_REQUISITO_LICENCA' codigo,'Potenciais de licenças' nome_pt,'Potential licenses' nome_en,'Potenciales de licencias' nome_es,
    'Analise o requisito legal e identifique somente potenciais de LICENCA que a empresa possa precisar. Responda exclusivamente JSON valido no formato {"potenciais":[{"codrequisitolegal":null,"tipo_potencial":"LICENCA","titulo":"","descricao":"","justificativa_ia":"","confianca_ia":0,"idioma_conteudo":"pt"}]}. Nao invente dados, codigos ou obrigacoes. Use lista vazia quando nao houver sugestao segura. Nao aprove nem rejeite.' prompt_pt,
    'Analyze the legal requirement and identify only potential LICENSES the company may need. Return exclusively valid JSON in the defined potentials format. Do not invent data, codes or obligations. Use an empty list when there is no safe suggestion. Do not approve or reject.' prompt_en,
    'Analiza el requisito legal e identifica solo posibles LICENCIAS que la empresa pueda necesitar. Devuelve exclusivamente JSON valido en el formato definido. No inventes datos, codigos ni obligaciones. Usa una lista vacia cuando no haya una sugerencia segura. No apruebes ni rechaces.' prompt_es
    UNION ALL SELECT 'ML_REQUISITO_MONITORAMENTO','Potenciais de medição e monitoramento','Potential measurement and monitoring','Potenciales de medición y monitoreo',
    'Analise o requisito legal e identifique somente potenciais de MEDIÇÃO E MONITORAMENTO. Retorne exclusivamente JSON valido com tipo_potencial MONITORAMENTO, titulo, descricao, justificativa_ia, confianca_ia e idioma_conteudo. Nao invente informacoes, aprove ou rejeite.' ,'Analyze the legal requirement and identify only potential MEASUREMENT AND MONITORING actions. Return exclusively valid JSON with type MONITORAMENTO and the required fields. Do not invent information, approve or reject.','Analiza el requisito legal e identifica solo potenciales de MEDICION Y MONITOREO. Devuelve exclusivamente JSON valido con tipo MONITORAMENTO y los campos requeridos. No inventes informacion, apruebes ni rechaces.'
    UNION ALL SELECT 'ML_REQUISITO_TREINAMENTO','Potenciais de treinamentos','Potential training','Potenciales de capacitación',
    'Analise o requisito legal e identifique somente potenciais de TREINAMENTO. Retorne exclusivamente JSON valido com tipo_potencial TREINAMENTO, titulo, descricao, justificativa_ia, confianca_ia e idioma_conteudo. Nao invente informacoes, aprove ou rejeite.','Analyze the legal requirement and identify only potential TRAINING actions. Return exclusively valid JSON with type TREINAMENTO and the required fields. Do not invent information, approve or reject.','Analiza el requisito legal e identifica solo potenciales de CAPACITACION. Devuelve exclusivamente JSON valido con tipo_potencial TREINAMENTO y los campos requeridos. No inventes informacion, apruebes ni rechaces.'
    UNION ALL SELECT 'ML_REQUISITO_INFRAESTRUTURA','Potenciais de infraestrutura','Potential infrastructure','Potenciales de infraestructura',
    'Analise o requisito legal e identifique somente potenciais de INFRAESTRUTURA. Retorne exclusivamente JSON valido com tipo_potencial INFRAESTRUTURA, titulo, descricao, justificativa_ia, confianca_ia e idioma_conteudo. Nao invente informacoes, aprove ou rejeite.','Analyze the legal requirement and identify only potential INFRASTRUCTURE actions. Return exclusively valid JSON with type INFRAESTRUTURA and the required fields. Do not invent information, approve or reject.','Analiza el requisito legal e identifica solo potenciales de INFRAESTRUCTURA. Devuelve exclusivamente JSON valido con tipo INFRAESTRUTURA y los campos requeridos. No inventes informacion, apruebes ni rechaces.'
    UNION ALL SELECT 'ML_REQUISITO_DOCUMENTOS','Potenciais de documentos e controles','Potential documents and controls','Potenciales de documentos y controles',
    'Analise o requisito legal e identifique somente potenciais de DOCUMENTOS ou CONTROLES necessarios para demonstrar e acompanhar o atendimento. Use tipo_potencial CONTROLE. Retorne exclusivamente JSON valido com titulo, descricao, justificativa_ia, confianca_ia e idioma_conteudo. Nao invente informacoes, aprove ou rejeite.','Analyze the legal requirement and identify only potential DOCUMENTS or CONTROLS needed to demonstrate and monitor compliance. Use type_potencial CONTROLE. Return exclusively valid JSON with the required fields. Do not invent information, approve or reject.','Analiza el requisito legal e identifica solo potenciales de DOCUMENTOS o CONTROLES necesarios para demostrar y acompanhar el cumplimiento. Usa tipo_potencial CONTROLE. Devuelve exclusivamente JSON valido con los campos requeridos. No inventes informacion, apruebes ni rechaces.'
) x
WHERE NOT EXISTS (SELECT 1 FROM ia_prompts p WHERE p.codigo=x.codigo);
